const nm=(a,id)=>(a.find(x=>x.id==id)||{}).n||'';
const tot=t=>{const sub=t.items.reduce((a,i)=>a+i.q*i.p,0),net=sub-N(t.disc),tax=net*N(t.tax)/100;return{sub,net,tax,total:net+tax}};
/* ---- bill discount split ----
   A bill-level discount is divided between the items so that each item's UNIT price drops in clean steps (default 0.050),
   e.g. 0.400 on [4 pcs @1.100, 20 pcs @0.950] -> first item -0.100 per pc (net 1.000), second item untouched.
   Among all clean splits the one closest to "in proportion to value" is used. If no clean split adds up exactly,
   the biggest clean part is used and the small remainder is spread in proportion (so totals / profit stay exact). */
const dsStep=()=>S.ds==null||S.ds===''?0.05:Math.max(0,N(S.ds));
function allocNice(it,Dc,step){const n=it.length,out=it.map(()=>0),r6=x=>Math.round(x*1e6)/1e6;if(!(Dc>0)||!n)return{nice:out,R:0,val:out,Dc:0};
 const U=Math.pow(10,dec()),val=it.map(x=>Math.max(0,x.q*x.p)),V=val.reduce((a,b)=>a+b,0);if(V<=0)return{nice:out,R:0,val,Dc:0};Dc=Math.min(Dc,V);
 const nice=out.slice(),st=N(step);
 if(st>0){const sU=Math.round(st*U),T=Math.round(Dc*U);
  if(sU>0&&T>=sU){const inc=it.map(x=>Math.round(x.q*sU)),kmax=it.map(x=>Math.max(0,Math.floor(x.p/st+1e-9))),gcd=(a,b)=>b?gcd(b,a%b):a;let g=0;inc.forEach(c=>{if(c>0)g=gcd(g,c)});
   if(g>0){const Tt=Math.floor(T/g);
    if(Tt<=3000&&n<=60){const ci=inc.map(c=>c/g),share=val.map(v=>Dc*U*v/V/g),INF=1e18,choice=[];let best=new Array(Tt+1).fill(INF);best[0]=0;
     for(let i=0;i<n;i++){const nb=new Array(Tt+1).fill(INF),ch=new Int32Array(Tt+1),km=ci[i]>=1?Math.min(kmax[i],Math.floor(Tt/ci[i])):0;
      for(let s=0;s<=Tt;s++){if(best[s]>=INF)continue;for(let k=0;k<=km;k++){const s2=s+k*ci[i];if(s2>Tt)break;const c=best[s]+Math.pow(k*ci[i]-share[i],2);if(c<nb[s2]){nb[s2]=c;ch[s2]=k}}}
      best=nb;choice.push(ch)}
     let s=Tt;while(s>0&&best[s]>=INF)s--;
     for(let i=n-1;i>=0;i--){const k=choice[i][s];nice[i]=k*ci[i]*g/U;s-=k*ci[i]}}}}}
 let R=Dc-nice.reduce((a,b)=>a+b,0);if(R<1e-9)R=0;
 return{nice:nice.map(r6),R:r6(R),val,Dc}}
function allocDisc(it,Dc,step){const r6=x=>Math.round(x*1e6)/1e6,{nice,R,val,Dc:D1}=allocNice(it,Dc,step),n=it.length;if(!(D1>0))return it.map(()=>0);Dc=D1;
 if(R>0){const cap=val.map((v,i)=>Math.max(0,v-nice[i])),C=cap.reduce((a,b)=>a+b,0);if(C>0)for(let i=0;i<n;i++)nice[i]+=R*cap[i]/C}
 const res=nice.map(r6);let diff=r6(Dc-res.reduce((a,b)=>a+b,0));if(Math.abs(diff)>0){let j=0;res.forEach((v,i)=>{if(val[i]-v>val[j]-res[j])j=i});res[j]=r6(res[j]+diff)}
 return res}
