// latest real purchase of a product (returns excluded); optional: skip one bill (ex) or limit to one supplier (sup)
const lastPu=(pid,ex,sup)=>{let b=null;D.pu.forEach(t=>{if(t.ret||t.id==ex||(sup&&t.pid!=sup))return;t.items.forEach(i=>{if(i.pid==pid&&(!b||t.date>b.t.date||(t.date==b.t.date&&t.id>b.t.id)))b={t,i}})});return b};
