const lastCost=p=>{if(N(p.cost)>0)return p.cost;const L=lastPu(p.id,window._eid);return L?L.i.p:p.cost};
function fifo(){const CM=S.cm||'fifo',ev=[],L={},net={},cost={},last={};
 D.pu.forEach(t=>{const g=t.items.reduce((a,i)=>a+i.q*i.p,0),kf=g>0?Math.max(0,g-N(t.disc))/g:1;/* bill discount is spread over the items in proportion to their value */t.items.forEach((i,k)=>ev.push({d:t.date,o:t.ret?1:0,id:t.id,k,pid:i.pid,q:i.q,p:i.p,cp:i.dd!=null&&i.q?i.p-i.dd/i.q:i.p*kf,ty:t.ret?'pr':'pu'}))});
 D.sa.forEach(t=>t.items.forEach((i,k)=>ev.push({d:t.date,o:t.ret?0:1,id:t.id,k,pid:i.pid,q:i.q,b:i.b,ty:t.ret?'sr':'sa'})));
 ev.sort((a,b)=>a.d<b.d?-1:a.d>b.d?1:a.o-b.o||a.id-b.id||a.k-b.k);
 D.p.forEach(p=>{L[p.id]=[];net[p.id]=0});
 ev.forEach(e=>{if(e.pid in net)net[e.pid]+=(e.ty=='pu'||e.ty=='sr')?e.q:-e.q});
 D.p.forEach(p=>{const u=stock(p.id)-net[p.id];if(u>0)L[p.id].push({q:u,c:N(p.cost),b:-1})});/* stock at the Product Price (opening / adjusted stock) = batch -1 */
 ev.forEach(e=>{const l=L[e.pid];if(!l)return;const pc=N((D.p.find(p=>p.id==e.pid)||{}).cost);
  if(e.ty=='pu')l.push({q:e.q,c:e.cp,rp:e.p,b:e.id});
  else if(e.ty=='sr'){const c=last[e.pid]??pc;l.push({q:e.q,c,b:0});cost[e.id+'_'+e.k]=c}
  else{let r=e.q,v=0;while(r>1e-9&&l.length){let j=e.ty=='pr'?l.findIndex(x=>(x.rp==null?x.c:x.rp)==e.p):CM=='batch'&&e.b?l.findIndex(x=>x.b==e.b):CM=='lifo'?l.length-1:0;if(j<0)j=CM=='lifo'&&e.ty=='sa'?l.length-1:0;const x=l[j],u=Math.min(r,x.q);v+=u*x.c;x.q-=u;r-=u;if(x.q<=1e-9)l.splice(j,1)}
   if(r>1e-9)v+=r*pc;if(e.ty=='sa'){const c=e.q?v/e.q:0;cost[e.id+'_'+e.k]=c;last[e.pid]=c}}});
 const v={};D.p.forEach(p=>v[p.id]=L[p.id].reduce((a,x)=>a+x.q*x.c,0));return{cost,val:v,lay:L}}
const QT=()=>D.qt||(D.qt=[]);let AG='c',PF='p';const cdays=x=>x&&x.days!=null&&x.days!==''?Math.max(0,N(x.days)):0;const od=(t,x)=>Math.floor((Date.parse(today())-Date.parse(t.date))/864e5)-cdays(x);
const alloc=(tid,ex)=>D.pay.concat((D.ls||[]).filter(l=>l.wo)).filter(p=>p.id!=ex).reduce((s,p)=>s+(p.al||[]).filter(e=>e.id==tid).reduce((a,e)=>a+N(e.a),0),0);
