 const rows=D.p.map(p=>{const q=stock(p.id,g),v=q*N(p.cost);T+=v;return[esc(p.n)+' <span class="k">'+esc(p.u1||'')+'</span>'+(p.sku?'<div class="k">'+esc(p.sku)+'</div>':''),q,`<input type="number" step="any" class="tk" data-p="${p.id}" data-sys="${q}" oninput="tkCalc()" style="width:84px">`,`<input type="number" step="any" class="tc" data-p="${p.id}" data-k="c" value="${N(p.cost)}" onchange="tkPrice(this)" oninput="tkCalc()" style="width:90px">`,`<input type="number" step="any" class="tc" data-p="${p.id}" data-k="s" value="${N(p.price)}" onchange="tkPrice(this)" style="width:90px">`,`<b class="tv" data-p="${p.id}">${M(v)}</b>`]});
