function tkCalc(){let T=0;document.querySelectorAll('.tk').forEach(i=>{const id=i.dataset.p,c=document.querySelector('.tc[data-p="'+id+'"][data-k="c"]'),q=i.value===''?N(i.dataset.sys):N(i.value),v=q*N(c&&c.value),o=document.querySelector('.tv[data-p="'+id+'"]');if(o)o.textContent=M(v);T+=v});['tkT','tkT2'].forEach(k=>{const t=$(k);if(t)t.textContent=M(T)})}
function tkPrice(el){const p=D.p.find(x=>x.id==el.dataset.p);if(!p)return;const c=el.dataset.k=='c',v=N(el.value),old=c?N(p.cost):N(p.price);
 if(el.value===''||v<0){el.value=old;tkCalc();return toast('Enter a valid price')}
 if(Math.abs(v-old)<1e-9)return;if(c)p.cost=v;else p.price=v;
 (D.log=D.log||[]).push({t:now(),u:ME?ME.n:'—',a:'Price Update',c:'Product',r:p.n+' '+(c?'purchase ':'selling ')+old+' → '+v});save();tkCalc();toast((c?'Purchase':'Selling')+' price saved: '+p.n)}
function tkApply(){let n=0;document.querySelectorAll('.tk').forEach(i=>{if(i.value==='')return;const p=D.p.find(x=>x.id==i.dataset.p),d=N(i.value)-stock(p.id,STG);if(Math.abs(d)>1e-9){addSt(p.id,STG,d);(D.log=D.log||[]).push({t:now(),u:ME?ME.n:'—',a:'Stock Take',c:'Product',r:p.n+' '+(d>0?'+':'')+d});n++}});save();toast(n?n+' item(s) adjusted':'No differences');go()}
