function osOf(pid){let net=0;D.pu.forEach(t=>t.items.forEach(i=>{if(i.pid==pid)net+=t.ret?-i.q:i.q}));D.sa.forEach(t=>t.items.forEach(i=>{if(i.pid==pid)net+=t.ret?i.q:-i.q}));return Math.round((stock(pid)-net)*1e6)/1e6}
// opening-stock godown: p.og (older products without it: the godown that holds most of the product)
function ogOf(p){if(D.g.some(g=>g.id==p.og))return p.og;let b=D.g[0].id,m=-Infinity;D.g.forEach(g=>{const s=stock(p.id,g.id);if(s>m+1e-9){m=s;b=g.id}});return b}
// opening stock per godown: p.ob = {godownId: qty}. Older products only have p.og (one godown) -> all of the opening stock sits there.
function obMap(p){const os=osOf(p.id),m={};
 if(p.ob&&typeof p.ob=='object')D.g.forEach(g=>{const v=N(p.ob[g.id]);if(v)m[g.id]=v});else if(os)m[ogOf(p)]=os;
 const sum=Object.values(m).reduce((a,b)=>a+b,0),diff=Math.round((os-sum)*1e6)/1e6;   // stock adjustments change the total: keep the split in step
 if(Math.abs(diff)>1e-9){let t=null,mx=-Infinity;for(const k in m)if(m[k]>mx){mx=m[k];t=k}if(t==null)t=ogOf(p);m[t]=Math.round(((m[t]||0)+diff)*1e6)/1e6;if(Math.abs(m[t])<1e-9)delete m[t]}
 return m}
const obTotal=m=>Math.round(Object.values(m).reduce((a,b)=>a+N(b),0)*1e6)/1e6;
function obLines(p){const m=obMap(p),L=D.g.filter(g=>N(m[g.id])).map(g=>`<div class="k gdl"><b>${esc(g.n)}</b>: ${N(m[g.id])}</div>`).join('');return L||'<span class="k">—</span>'}
// plan a new opening-stock split {godownId:qty}: every godown must stay >= 0 after the change
function osPlan(p,nm2){const old=obMap(p),del={},nw={};
 for(const g of D.g){const v=N(nm2[g.id]);if(!(v>=0))return{err:'opening stock cannot be negative'};const d=Math.round((v-N(old[g.id]))*1e6)/1e6;
  if(d&&stock(p.id,g.id)+d<-1e-9)return{err:'cannot lower opening stock in '+g.n+' — it has already been sold or moved out of there, stock would go negative'};
  if(d)del[g.id]=d;if(v)nw[g.id]=v}
 return{del,nw}}
function osApply(p,pl){for(const g in pl.del)addSt(p.id,+g,pl.del[g]);p.ob=pl.nw;const k=Object.keys(pl.nw).sort((a,b)=>pl.nw[b]-pl.nw[a])[0];if(k)p.og=+k}
